  "This quiz is too large to save.": { en: "This quiz is too large to save.", ar: "هذا الاختبار كبير جدًا بحيث لا يمكن حفظه.", uk: "Ця вікторина завелика для збереження.", fr: "Ce quiz est trop volumineux pour être enregistré.", de: "Dieses Quiz ist zu groß zum Speichern.", tr: "Bu test kaydedilemeyecek kadar büyük." },
