  "🔗 Copy join link": { en: "🔗 Copy join link", ar: "🔗 نسخ رابط الانضمام", uk: "🔗 Копіювати посилання", fr: "🔗 Copier le lien de participation", de: "🔗 Beitrittslink kopieren", tr: "🔗 Katılma bağlantısını kopyala" },
