  "Thanks — your report was sent.": { en: "Thanks — your report was sent.", ar: "شكرًا — تم إرسال بلاغك.", uk: "Дякуємо — ваше повідомлення надіслано.", fr: "Merci — votre signalement a été envoyé.", de: "Danke — dein Bericht wurde gesendet.", tr: "Teşekkürler — raporunuz gönderildi." },
  "Something went wrong": { en: "Something went wrong", ar: "حدث خطأ ما", uk: "Щось пішло не так", fr: "Un problème est survenu", de: "Etwas ist schiefgelaufen", tr: "Bir şeyler ters gitti" },
  "Sorry about that — our team has been automatically notified.": { en: "Sorry about that — our team has been automatically notified.", ar: "نعتذر عن ذلك — تم إخطار فريقنا تلقائيًا.", uk: "Перепрошуємо — нашу команду вже сповіщено автоматично.", fr: "Désolé — notre équipe a été automatiquement avertie.", de: "Entschuldigung — unser Team wurde automatisch benachrichtigt.", tr: "Bunun için üzgünüz — ekibimiz otomatik olarak bilgilendirildi." },
  "Add any details (optional):": { en: "Add any details (optional):", ar: "أضف أي تفاصيل (اختياري):", uk: "Додайте деталі (необов'язково):", fr: "Ajoutez des détails (facultatif) :", de: "Füge weitere Details hinzu (optional):", tr: "Varsa ayrıntı ekleyin (isteğe bağlı):" },
