  "🗳️ Vote recorded!": { en: "🗳️ Vote recorded!", ar: "🗳️ تم تسجيل صوتك!", uk: "🗳️ Голос зараховано!", fr: "🗳️ Vote enregistré !", de: "🗳️ Stimme erfasst!", tr: "🗳️ Oy kaydedildi!" },
