  "Sound effects on/off": { en: "Sound effects on/off", ar: "المؤثرات الصوتية تشغيل/إيقاف", uk: "Звукові ефекти увімк./вимк.", fr: "Effets sonores activés/désactivés", de: "Soundeffekte an/aus", tr: "Ses efektleri açık/kapalı" },
  "Toggle sound": { en: "Toggle sound", ar: "تبديل الصوت", uk: "Перемкнути звук", fr: "Activer/désactiver le son", de: "Ton umschalten", tr: "Sesi aç/kapat" },
  "Type your answer...": { en: "Type your answer...", ar: "اكتب إجابتك...", uk: "Введіть відповідь...", fr: "Saisissez votre réponse...", de: "Gib deine Antwort ein...", tr: "Yanıtınızı yazın..." },
  "No quiz specified.": { en: "No quiz specified.", ar: "لم يتم تحديد اختبار.", uk: "Вікторину не вказано.", fr: "Aucun quiz spécifié.", de: "Kein Quiz angegeben.", tr: "Hiçbir test belirtilmedi." },
  "Quiz not found or not shared.": { en: "Quiz not found or not shared.", ar: "الاختبار غير موجود أو غير مُشارك.", uk: "Вікторину не знайдено або нею не поділилися.", fr: "Quiz introuvable ou non partagé.", de: "Quiz nicht gefunden oder nicht geteilt.", tr: "Test bulunamadı veya paylaşılmadı." },
  "This quiz has no playable questions yet.": { en: "This quiz has no playable questions yet.", ar: "لا يحتوي هذا الاختبار على أسئلة قابلة للعب بعد.", uk: "У цій вікторині ще немає запитань для гри.", fr: "Ce quiz n'a pas encore de questions jouables.", de: "Dieses Quiz hat noch keine spielbaren Fragen.", tr: "Bu testte henüz oynanabilir soru yok." },
  "Could not load this quiz. The host may not have shared it.": { en: "Could not load this quiz. The host may not have shared it.", ar: "تعذّر تحميل هذا الاختبار. قد لا يكون المضيف قد شاركه.", uk: "Не вдалося завантажити вікторину. Можливо, ведучий нею не поділився.", fr: "Impossible de charger ce quiz. L'hôte ne l'a peut-être pas partagé.", de: "Dieses Quiz konnte nicht geladen werden. Der Host hat es möglicherweise nicht geteilt.", tr: "Bu test yüklenemedi. Sunucu paylaşmamış olabilir." },
  "Loading…": { en: "Loading…", ar: "جارٍ التحميل…", uk: "Завантаження…", fr: "Chargement…", de: "Wird geladen…", tr: "Yükleniyor…" },
