  "Activity unavailable": { en: "Activity unavailable", ar: "النشاط غير متاح", uk: "Активність недоступна", fr: "Activité indisponible", de: "Aktivität nicht verfügbar", tr: "Etkinlik kullanılamıyor" },
  "This activity is no longer available — the video was removed or made private.": { en: "This activity is no longer available — the video was removed or made private.", ar: "لم يعد هذا النشاط متاحًا — تمت إزالة الفيديو أو جُعل خاصًا.", uk: "Ця активність більше недоступна — відео видалено або зроблено приватним.", fr: "Cette activité n'est plus disponible — la vidéo a été supprimée ou rendue privée.", de: "Diese Aktivität ist nicht mehr verfügbar — das Video wurde entfernt oder auf privat gesetzt.", tr: "Bu etkinlik artık kullanılamıyor — video kaldırıldı veya gizli yapıldı." },
  "🎬 Interactive video — it will pause to ask you questions.": { en: "🎬 Interactive video — it will pause to ask you questions.", ar: "🎬 فيديو تفاعلي — سيتوقف ليطرح عليك الأسئلة.", uk: "🎬 Інтерактивне відео — воно зупинятиметься, щоб поставити запитання.", fr: "🎬 Vidéo interactive — elle se met en pause pour vous poser des questions.", de: "🎬 Interaktives Video — es pausiert, um dir Fragen zu stellen.", tr: "🎬 Etkileşimli video — size soru sormak için duraklayacak." },
  "Done! 🎉": { en: "Done! 🎉", ar: "تم! 🎉", uk: "Готово! 🎉", fr: "Terminé ! 🎉", de: "Fertig! 🎉", tr: "Bitti! 🎉" },
