  "You're in!": { en: "You're in!", ar: "أنت في اللعبة!", uk: "Ви в грі!", fr: "Vous y êtes !", de: "Du bist dabei!", tr: "Katıldınız!" },
  "Choose your nickname": { en: "Choose your nickname", ar: "اختر اسمك المستعار", uk: "Оберіть нікнейм", fr: "Choisissez votre pseudo", de: "Wähle deinen Spitznamen", tr: "Takma adınızı seçin" },
  "Random nickname": { en: "Random nickname", ar: "اسم عشوائي", uk: "Випадковий нікнейм", fr: "Pseudo aléatoire", de: "Zufälliger Spitzname", tr: "Rastgele takma ad" },
  "👥 Team name (players with the same name share a score)": { en: "👥 Team name (players with the same name share a score)", ar: "👥 اسم الفريق (اللاعبون بنفس الاسم يتشاركون النتيجة)", uk: "👥 Назва команди (гравці з однаковою назвою мають спільний рахунок)", fr: "👥 Nom d'équipe (les joueurs portant le même nom partagent un score)", de: "👥 Teamname (Spieler mit demselben Namen teilen sich eine Punktzahl)", tr: "👥 Takım adı (aynı adı kullanan oyuncular puanı paylaşır)" },
  "e.g. Red Dragons": { en: "e.g. Red Dragons", ar: "مثال: التنانين الحمراء", uk: "напр. Червоні дракони", fr: "ex. Dragons Rouges", de: "z. B. Rote Drachen", tr: "örn. Kızıl Ejderler" },
