  "Failed to join. Try again.": { en: "Failed to join. Try again.", ar: "تعذّر الانضمام. حاول مرة أخرى.", uk: "Не вдалося приєднатися. Спробуйте ще раз.", fr: "Échec de la connexion. Réessayez.", de: "Beitritt fehlgeschlagen. Versuche es erneut.", tr: "Katılınamadı. Tekrar deneyin." },
  "Enter a nickname": { en: "Enter a nickname", ar: "أدخل اسمًا مستعارًا", uk: "Введіть нікнейм", fr: "Saisissez un pseudo", de: "Gib einen Spitznamen ein", tr: "Bir takma ad girin" },
  "Invalid game": { en: "Invalid game", ar: "لعبة غير صالحة", uk: "Некоректна гра", fr: "Partie non valide", de: "Ungültiges Spiel", tr: "Geçersiz oyun" },
