  "⚔️ Battle Royale": { en: "⚔️ Battle Royale", ar: "⚔️ Battle Royale", uk: "⚔️ Королівська битва", fr: "⚔️ Battle Royale", de: "⚔️ Battle Royale", tr: "⚔️ Battle Royale" },
  "Miss a question, you're out. Last one standing wins!": { en: "Miss a question, you're out. Last one standing wins!", ar: "تخطئ سؤالًا فتخرج. آخر لاعب صامد يفوز!", uk: "Помилився — вибуваєш. Перемагає той, хто лишився останнім!", fr: "Ratez une question et vous êtes éliminé. Le dernier en lice gagne !", de: "Verpasse eine Frage und du bist raus. Der Letzte, der übrig bleibt, gewinnt!", tr: "Bir soruyu kaçırırsanız elenirsiniz. Ayakta kalan son kişi kazanır!" },
  "👥 Team mode": { en: "👥 Team mode", ar: "👥 نمط الفرق", uk: "👥 Командний режим", fr: "👥 Mode équipe", de: "👥 Teammodus", tr: "👥 Takım modu" },
  "Players join a team; scores are pooled.": { en: "Players join a team; scores are pooled.", ar: "ينضم اللاعبون إلى فريق وتُجمع النقاط.", uk: "Гравці приєднуються до команди, рахунки сумуються.", fr: "Les joueurs rejoignent une équipe ; les scores sont mis en commun.", de: "Die Spieler treten einem Team bei; die Punkte werden zusammengelegt.", tr: "Oyuncular bir takıma katılır; puanlar birleştirilir." },
  "(no past games yet)": { en: "(no past games yet)", ar: "(لا توجد ألعاب سابقة بعد)", uk: "(минулих ігор ще немає)", fr: "(pas encore de parties passées)", de: "(noch keine vergangenen Spiele)", tr: "(henüz geçmiş oyun yok)" },
