  "Create Game Room": { en: "Create Game Room", ar: "إنشاء غرفة اللعب", uk: "Створити ігрову кімнату", fr: "Créer une salle de jeu", de: "Spielraum erstellen", tr: "Oyun Odası Oluştur" },
