  "📱 Scan the QR code to join instantly": { en: "📱 Scan the QR code to join instantly", ar: "📱 امسح رمز QR للانضمام فورًا", uk: "📱 Скануйте QR-код, щоб приєднатися миттєво", fr: "📱 Scannez le QR code pour rejoindre instantanément", de: "📱 Scanne den QR-Code, um sofort beizutreten", tr: "📱 Anında katılmak için QR kodunu tarayın" },
