  "Or email it to players": { en: "Or email it to players", ar: "أو أرسله بالبريد للاعبين", uk: "Або надішліть його гравцям на email", fr: "Ou envoyez-le par e-mail aux joueurs", de: "Oder per E-Mail an die Spieler senden", tr: "Veya oyunculara e-posta ile gönderin" },
  "✓ Invitations sent!": { en: "✓ Invitations sent!", ar: "✓ تم إرسال الدعوات!", uk: "✓ Запрошення надіслано!", fr: "✓ Invitations envoyées !", de: "✓ Einladungen gesendet!", tr: "✓ Davetler gönderildi!" },
  "Could not send. Check the addresses and try again.": { en: "Could not send. Check the addresses and try again.", ar: "تعذّر الإرسال. تحقق من العناوين وحاول مرة أخرى.", uk: "Не вдалося надіслати. Перевірте адреси і спробуйте ще раз.", fr: "Échec de l'envoi. Vérifiez les adresses et réessayez.", de: "Senden fehlgeschlagen. Überprüfe die Adressen und versuche es erneut.", tr: "Gönderilemedi. Adresleri kontrol edip tekrar deneyin." },
  "Close": { en: "Close", ar: "إغلاق", uk: "Закрити", fr: "Fermer", de: "Schließen", tr: "Kapat" },
