  "Share a self-paced assignment link — copy it or email it": { en: "Share a self-paced assignment link — copy it or email it", ar: "شارك رابط واجب ذاتي التوقيت — انسخه أو أرسله بالبريد", uk: "Поділіться посиланням на завдання — скопіюйте його або надішліть поштою", fr: "Partagez un lien de devoir en autonomie — copiez-le ou envoyez-le par e-mail", de: "Teile einen Aufgabenlink zum Selbststudium — kopiere ihn oder sende ihn per E-Mail", tr: "Kendi hızında bir ödev bağlantısı paylaşın — kopyalayın veya e-posta ile gönderin" },
  "Enter one or more emails, separated by commas": { en: "Enter one or more emails, separated by commas", ar: "أدخل بريدًا أو أكثر مفصولة بفواصل", uk: "Введіть одну або кілька адрес через кому", fr: "Saisissez une ou plusieurs adresses e-mail, séparées par des virgules", de: "Gib eine oder mehrere E-Mail-Adressen ein, durch Kommas getrennt", tr: "Virgülle ayırarak bir veya daha fazla e-posta girin" },
